public struct ConnectConfig {
    public var host: String
    public var port: UInt16
    public var useTls: Bool
    public var userId: String
    public var deviceId: String
    public var authToken: String
    public var clientVersion: String
    public var resumeAfterSeq: UInt64
    public var pingIntervalSecs: UInt64
    public var autoReconnect: Bool
    public var maxReconnectAttempts: UInt32
    public var useWebsocket: Bool
    public var wsUrl: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(host: String, port: UInt16, useTls: Bool, userId: String, deviceId: String, authToken: String, clientVersion: String, resumeAfterSeq: UInt64, pingIntervalSecs: UInt64, autoReconnect: Bool, maxReconnectAttempts: UInt32, useWebsocket: Bool, wsUrl: String) {
        self.host = host
        self.port = port
        self.useTls = useTls
        self.userId = userId
        self.deviceId = deviceId
        self.authToken = authToken
        self.clientVersion = clientVersion
        self.resumeAfterSeq = resumeAfterSeq
        self.pingIntervalSecs = pingIntervalSecs
        self.autoReconnect = autoReconnect
        self.maxReconnectAttempts = maxReconnectAttempts
        self.useWebsocket = useWebsocket
        self.wsUrl = wsUrl
    }
}



extension ConnectConfig: Equatable, Hashable {
    public static func ==(lhs: ConnectConfig, rhs: ConnectConfig) -> Bool {
        if lhs.host != rhs.host {
            return false
        }
        if lhs.port != rhs.port {
            return false
        }
        if lhs.useTls != rhs.useTls {
            return false
        }
        if lhs.userId != rhs.userId {
            return false
        }
        if lhs.deviceId != rhs.deviceId {
            return false
        }
        if lhs.authToken != rhs.authToken {
            return false
        }
        if lhs.clientVersion != rhs.clientVersion {
            return false
        }
        if lhs.resumeAfterSeq != rhs.resumeAfterSeq {
            return false
        }
        if lhs.pingIntervalSecs != rhs.pingIntervalSecs {
            return false
        }
        if lhs.autoReconnect != rhs.autoReconnect {
            return false
        }
        if lhs.maxReconnectAttempts != rhs.maxReconnectAttempts {
            return false
        }
        if lhs.useWebsocket != rhs.useWebsocket {
            return false
        }
        if lhs.wsUrl != rhs.wsUrl {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(host)
        hasher.combine(port)
        hasher.combine(useTls)
        hasher.combine(userId)
        hasher.combine(deviceId)
        hasher.combine(authToken)
        hasher.combine(clientVersion)
        hasher.combine(resumeAfterSeq)
        hasher.combine(pingIntervalSecs)
        hasher.combine(autoReconnect)
        hasher.combine(maxReconnectAttempts)
        hasher.combine(useWebsocket)
        hasher.combine(wsUrl)
    }
}


