public enum LaneError {

    
    
    case Io(message: String
    )
    case Protocol(message: String
    )
    case AuthFailed
    case Closed
    case Timeout(message: String
    )
    case Media(message: String
    )
    case E2ee(message: String
    )
    case InvalidArgument(message: String
    )
    case NotConnected
    case Internal(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeLaneError: FfiConverterRustBuffer {
    typealias SwiftType = LaneError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> LaneError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Protocol(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .AuthFailed
        case 4: return .Closed
        case 5: return .Timeout(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Media(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .E2ee(
            message: try FfiConverterString.read(from: &buf)
            )
        case 8: return .InvalidArgument(
            message: try FfiConverterString.read(from: &buf)
            )
        case 9: return .NotConnected
        case 10: return .Internal(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: LaneError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Io(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Protocol(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case .AuthFailed:
            writeInt(&buf, Int32(3))
        
        
        case .Closed:
            writeInt(&buf, Int32(4))
        
        
        case let .Timeout(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Media(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .E2ee(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidArgument(message):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(message, into: &buf)
            
        
        case .NotConnected:
            writeInt(&buf, Int32(9))
        
        
        case let .Internal(message):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


